   if j in piv:x^=piv[j]
   else:piv[j]=x;break
 return len(piv)
def nullspace(rows,n):
 rows=rows[:];piv=[];i=0
 for c in range(n):
  j=next((j for j in range(i,len(rows)) if rows[j]>>c&1),None)
  if j is None:continue
  rows[i],rows[j]=rows[j],rows[i]
